        "id": "569916",
        "title": "Maintenance Unfolded",
        "difficulty": "easy",
        "description": "<p class=\"\" data-start=\"0\" data-end=\"235\">You&rsquo;ve been asked by your friend Zara at GalaxyNet to prepare a daily roster showing which maintenance tasks run on which dates. Dates and maintenance windows are stored separately, so you must expand each window into individual dates.</p>\n<ul>\n<li data-start=\"239\" data-end=\"300\">The &lsquo;calendar&rsquo; table has &lsquo;dt&rsquo;. Each row is a calendar date.</li>\n<li data-start=\"303\" data-end=\"460\">The &lsquo;maintenance&rsquo; table has &lsquo;task_id&rsquo;, &lsquo;task_name&rsquo;, &lsquo;start_date&rsquo;, and &lsquo;end_date&rsquo;. &lsquo;task_id&rsquo; is primary key; each row describes when a task begins and ends.</li>\n</ul>\n<p class=\"\" data-start=\"462\" data-end=\"573\">Your task is to list each maintenance task with every calendar date that falls between its start and end dates.</p>\n<p class=\"\" data-start=\"575\" data-end=\"683\">The output columns should be &lsquo;task_name&rsquo; and &lsquo;dt&rsquo;, ordered by &lsquo;task_name&rsquo; ascending, then by &lsquo;dt&rsquo; ascending.</p>",
        "schema": "CREATE TABLE calendar (dt DATE);\nCREATE TABLE maintenance (\n  task_id INT PRIMARY KEY,\n  task_name VARCHAR(100),\n  start_date DATE,\n  end_date DATE\n);\nINSERT INTO calendar VALUES\n  ('2025-01-01'),\n  ('2025-01-02'),\n  ('2025-01-03'),\n  ('2025-01-04'),\n  ('2025-01-05'),\n  ('2025-01-06'),\n  ('2025-01-07'),\n  ('2025-01-08'),\n  ('2025-01-09'),\n  ('2025-01-10');\nINSERT INTO maintenance VALUES\n  (1, 'Relay Check', '2025-01-01', '2025-01-03'),\n  (2, 'Shield Calibration', '2025-01-02', '2025-01-05'),\n  (3, 'Life Support Check', '2025-01-04', '2025-01-06'),\n  (4, 'Navigation Update', '2025-01-05', '2025-01-08'),\n  (5, 'Engine Diagnostics', '2025-01-07', '2025-01-09'),\n  (6, 'Hull Inspection', '2025-01-09', '2025-01-10');",
