        "id": "570578",
        "title": "Revenue Share",
        "difficulty": "medium",
        "description": "<p>The city council needs a clear picture of how much each kind of facility is bringing in. They&rsquo;ve turned to you to calculate the earnings and show each category&rsquo;s slice of the pie.</p>\n<p>You are given two tables: &lsquo;facilities&rsquo; and &lsquo;transactions&rsquo;.</p>\n<ul>\n<li data-start=\"124\" data-end=\"224\">The 'facilities' table includes columns 'facility_id', 'facility_name', and 'facility_type'.</li>\n<li data-start=\"227\" data-end=\"381\">The 'transactions' table logs payment details for each facility, with columns 'transaction_id', 'facility_id', 'amount', and 'transaction_date'.</li>\n</ul>\n<p data-start=\"383\" data-end=\"403\">You are required to:</p>\n<ul>\n<li data-start=\"407\" data-end=\"470\">Calculate the total revenue generated for each facility_type.</li>\n<li data-start=\"473\" data-end=\"640\">Compute each facility_type's <strong data-start=\"504\" data-end=\"521\">revenue share</strong> as a percentage of the overall revenue, <strong data-start=\"562\" data-end=\"595\">rounded to two decimal places</strong> and expressed as a string with a '%' symbol.</li>\n</ul>\n<p data-start=\"642\" data-end=\"789\" data-is-last-node=\"\" data-is-only-node=\"\">The final output should include columns 'facility_type', 'total_revenue', and 'revenue_share', ordered by total_revenue in descending order.</p>",
        "schema": "CREATE TABLE facilities (\n  facility_id INT PRIMARY KEY,\n  facility_name VARCHAR(100),\n  facility_type VARCHAR(20)\n);\nCREATE TABLE transactions (\n  transaction_id INT PRIMARY KEY,\n  facility_id INT,\n  amount DECIMAL(10,2),\n  transaction_date DATE\n);\nINSERT INTO facilities VALUES\n  (101, 'Steelworks',      'Blacksmith'),\n  (102, 'Northern Beacon', 'Lighthouse');\nINSERT INTO transactions VALUES\n  (101, 101, 250.00, '2025-06-01'),\n  (102, 101, 150.00, '2025-06-02'),\n  (103, 102, 120.00, '2025-06-01'),\n  (104, 102, 180.00, '2025-06-03'),\n  (105, 101, 100.00, '2025-06-04');\n\n",
