        "sample_testcases": [{"input":"-- Table Definitions\nCREATE TABLE bonding_energy (\n    element_1 VARCHAR(2),\n    element_2 VARCHAR(2),\n    energy INT,\n    PRIMARY KEY (element_1, element_2)\n);\n\nCREATE TABLE compounds (\n    compound_id INT PRIMARY KEY,\n    compound_name VARCHAR(50),\n    compound_formulae VARCHAR(100)\n);\n\n-- Sample Data\nINSERT INTO bonding_energy VALUES\n('C', 'O', 40),\n('H', 'O', 30),\n('C', 'H', 25),\n('Cl', 'Na', 45);\n\nINSERT INTO compounds VALUES\n(1, 'Carbon Dioxide', 'O-C-O'),\n(2, 'Water', 'H-O-H'),\n(3, 'Methane', 'H-C-H-H-H'),\n(4, 'Table Salt', 'Na-Cl');","output":"compound_id\tcompound_name\ttotal_energy\n1\tCarbon Dioxide\t80\n2\tWater\t60\n3\tMethane\t50\n4\tTable Salt\t45\n","explanation":"<p><strong>bonding_energy:&nbsp;</strong></p>\n<table>\n<tbody>\n<tr>\n<td>\n<p><strong>element_1</strong></p>\n</td>\n<td>\n<p><strong>element_2</strong></p>\n</td>\n<td>\n<p><strong>energy</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>C</strong></p>\n</td>\n<td>\n<p><strong>O</strong></p>\n</td>\n<td>\n<p><strong>40</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>H</strong></p>\n</td>\n<td>\n<p><strong>O</strong></p>\n</td>\n<td>\n<p><strong>30</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>C</strong></p>\n</td>\n<td>\n<p><strong>H</strong></p>\n</td>\n<td>\n<p><strong>25</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>Cl</strong></p>\n</td>\n<td>\n<p><strong>Na</strong></p>\n</td>\n<td>\n<p><strong>45</strong></p>\n</td>\n</tr>\n</tbody>\n</table>\n<p><strong>compounds:&nbsp;</strong></p>\n<table>\n<tbody>\n<tr>\n<td>\n<p><strong>compound_id</strong></p>\n</td>\n<td>\n<p><strong>compound_name</strong></p>\n</td>\n<td>\n<p><strong>compound_formulae</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>1</strong></p>\n</td>\n<td>\n<p><strong>Carbon Dioxide</strong></p>\n</td>\n<td>\n<p><strong>O-C-O</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>2</strong></p>\n</td>\n<td>\n<p><strong>Water</strong></p>\n</td>\n<td>\n<p><strong>H-O-H</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>3</strong></p>\n</td>\n<td>\n<p><strong>Methane</strong></p>\n</td>\n<td>\n<p><strong>H-C-H-H-H</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>4</strong></p>\n</td>\n<td>\n<p><strong>Table Salt</strong></p>\n</td>\n<td>\n<p><strong>Na-Cl</strong></p>\n</td>\n</tr>\n</tbody>\n</table>\n<p><br /><br /></p>"},{"input":"CREATE TABLE bonding_energy (\n    element_1 VARCHAR(2),\n    element_2 VARCHAR(2),\n    energy INT,\n    PRIMARY KEY (element_1, element_2)\n);\n\nCREATE TABLE compounds (\n    compound_id INT PRIMARY KEY,\n    compound_name VARCHAR(50),\n    compound_formulae VARCHAR(100)\n);\nINSERT INTO bonding_energy VALUES\n('Na', 'Cl', 50),\n('Ca', 'Cl', 35),\n('H', 'Cl', 20);\n\nINSERT INTO compounds VALUES\n(1, 'Sodium Chloride', 'Na-Cl'),\n(2, 'Calcium Chloride', 'Cl-Ca-Cl'),\n(3, 'Hydrochloric Acid', 'H-Cl'),\n(4, 'Chlorine Gas', 'Cl-Cl');","output":"compound_id\tcompound_name\ttotal_energy\n1\tSodium Chloride\t50\n2\tCalcium Chloride\t70\n3\tHydrochloric Acid\t20\n","explanation":"<p><strong>bonding_energy:&nbsp;</strong></p>\n<table>\n<tbody>\n<tr>\n<td>\n<p><strong>element_1</strong></p>\n</td>\n<td>\n<p><strong>element_2</strong></p>\n</td>\n<td>\n<p><strong>energy</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>Na</strong></p>\n</td>\n<td>\n<p><strong>Cl</strong></p>\n</td>\n<td>\n<p><strong>50</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>Ca</strong></p>\n</td>\n<td>\n<p><strong>Cl</strong></p>\n</td>\n<td>\n<p><strong>35</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>H</strong></p>\n</td>\n<td>\n<p><strong>Cl</strong></p>\n</td>\n<td>\n<p><strong>20</strong></p>\n</td>\n</tr>\n</tbody>\n</table>\n<p><strong>compounds:&nbsp;</strong></p>\n<table>\n<tbody>\n<tr>\n<td>\n<p><strong>compound_id</strong></p>\n</td>\n<td>\n<p><strong>compound_name</strong></p>\n</td>\n<td>\n<p><strong>compound_formulae</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>1</strong></p>\n</td>\n<td>\n<p><strong>Sodium Chloride</strong></p>\n</td>\n<td>\n<p><strong>Na-Cl</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>2</strong></p>\n</td>\n<td>\n<p><strong>Calcium Chloride</strong></p>\n</td>\n<td>\n<p><strong>Cl-Ca-Cl</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>3</strong></p>\n</td>\n<td>\n<p><strong>Hydrochloric Acid</strong></p>\n</td>\n<td>\n<p><strong>H-Cl</strong></p>\n</td>\n</tr>\n<tr>\n<td>\n<p><strong>4</strong></p>\n</td>\n<td>\n<p><strong>Chlorine Gas</strong></p>\n</td>\n<td>\n<p><strong>Cl-Cl</strong></p>\n</td>\n</tr>\n</tbody>\n</table>"}]
